(()=>{let ready=false,promise=null;function load(){if(promise)return promise;promise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.type='module';script.src='/motion-source.js';script.onload=()=>{ready=true;resolve()};script.onerror=()=>{promise=null;script.remove();reject(new Error('Optional exhibit unavailable'))};document.head.appendChild(script)});return promise}const forge=document.querySelector('#forge');if(forge){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){load().catch(()=>{});observer.disconnect()}},{rootMargin:'200px'});observer.observe(forge)}document.addEventListener('click',e=>{const button=e.target.closest('#sticker-open,#open-sculpture,#artwork-open,[data-episode]');if(!button||ready)return;e.preventDefault();e.stopImmediatePropagation();const label=button.textContent;button.setAttribute('aria-busy','true');load().then(()=>{button.removeAttribute('aria-busy');button.click()}).catch(()=>{button.removeAttribute('aria-busy');button.textContent=label;const live=document.querySelector('.toast');if(live){live.hidden=false;live.textContent='This optional exhibit could not load. Please try again.'}})},true)})();
